def transform(grid):
    h, w = len(grid), len(grid[0])
    # The divider is the constant, nonzero column.
    divider = next(c for c in range(w)
                   if grid[0][c] != 0 and all(row[c] == grid[0][c] for row in grid))
    left_cols = range(divider)
    right_cols = range(divider + 1, w)

    def background(cols):
        counts = {}
        for row in grid:
            for c in cols:
                counts[row[c]] = counts.get(row[c], 0) + 1
        return max(counts, key=counts.get)

    left_bg = background(left_cols)
    right_bg = background(right_cols)
    return [
        [0 if row[c] != left_bg or row[divider + 1 + c] != right_bg else 3
         for c in range(divider)]
        for row in grid
    ]
