    # Find the solid separator column or row.
    sep_col = next((c for c in range(w)
                    if all(grid[r][c] == grid[0][c] for r in range(h))), None)

    if sep_col is not None:
        left = [row[:sep_col] for row in grid]
        right = [row[sep_col + 1:] for row in grid]
        width = min(len(left[0]), len(right[0]))
        colors_left = {v for row in left for v in row}
        colors_right = {v for row in right for v in row}
        mismatch = next(iter(colors_left & colors_right))
        return [
            [3 if left[r][c] == right[r][c] else mismatch for c in range(width)]
            for r in range(h)
        ]

    sep_row = next(r for r in range(h)
                   if all(v == grid[r][0] for v in grid[r]))
    top = grid[:sep_row]
