    colors_top = {v for row in top for v in row}
    colors_bottom = {v for row in bottom for v in row}
    mismatch = next(iter(colors_top & colors_bottom))
    return [
        [3 if top[r][c] == bottom[r][c] else mismatch for c in range(w)]
        for r in range(height)
    ]
